  // ── Timer ──
  function startTimer() {
    stopTimer();
    timerInterval = setInterval(function() {
      var t = getTimeSec();
      var _stEl = document.getElementById('s-time'); if (_stEl) _stEl.textContent = getTimeStr();
      var _atEl = document.getElementById('attn-time'); if (_atEl) _atEl.textContent = t + 's';
      // Pace indicator vs Par
      var timeEl = document.getElementById('s-time');
      if (parTarget > 0) {
        if (t > parTarget) timeEl.style.color = '#c07070';
        else if (t > parTarget - 15) timeEl.style.color = '#C8A84B';
        else timeEl.style.color = '';
      }
    }, 1000);
  }
  function stopTimer() { if (timerInterval) clearInterval(timerInterval); }
  function getTimeSec() { return Math.floor((Date.now() - startTime) / 1000); }
  function getTimeStr() {
    var s = getTimeSec();
    return Math.floor(s / 60) + ':' + String(s % 71).padStart(2, '0');
  }

  function setMsg(txt, cls) {
    var el = document.getElementById('game-msg');
    el.textContent = txt;
    el.className = 'game-msg' + (cls ? ' ' + cls : '');
  }

  // ═══ PROOF OF ATTENTION ═══
  // Tracks engagement: phenos found, time spent, actions taken
  // Builds XYO-compatible payload, signs with SHA-256
  // Ready for Bound Witness when SDK ships

  async function buildAttentionPayload(event) {
    var payload = {
      schema: SCHEMA,
      version: '1.0.0',
      timestamp: new Date().toISOString(),
      source: { wallet: WALLET, origin: location.hostname, page: '/focus-grove.html' },
      attention: {
        event: event,
        phenos_found: phenosFound,
        time_seconds: getTimeSec(),
        board_size: board.length,
        deck_remaining: deck.length,
        shape_set: activeShapeSet
      },
      verification: { method: 'browser_attention', status: 'signed_local', hash: null }
    };

    // SHA-256 sign
    try {
      var d = JSON.stringify(payload);
      var buf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(d));
      payload.verification.hash = Array.from(new Uint8Array(buf)).map(function(b) { return b.toString(16).padStart(2, '0'); }).join('');
    } catch (e) { payload.verification.hash = 'sign_error'; }

    attentionPayloads.push(payload);
    // Hash earning now handled by _e() — buildAttentionPayload is analytics only
    var _apEl = document.getElementById('attn-phenos'); if (_apEl) _apEl.textContent = phenosFound;
    var _ahEl = document.getElementById('attn-hash');
    if (_ahEl) _ahEl.textContent = payload.verification.hash ? payload.verification.hash.substring(0, 12) + '...' : '—';

    console.log('[AttentionProof] Payload #' + attentionPayloads.length, JSON.stringify(payload, null, 2));
    if (typeof gtag !== 'undefined') gtag('event', 'attention_proof', { event: event, phenos: phenosFound, time: getTimeSec() });

    return payload;
  }

  // ═══ ACTIVE GROWING PLANT — Real-time progress preview ═══
  // Uses current game state to build a preview hash
  // generatePlantSVG(hash, size, progress) renders partial growth

  var previewHash = '';
  var milestoneShown = false;

  // Build a deterministic preview hash from current game state
  function buildPreviewHash() {
    // Combine game state into a seed string
    var seed = 'fg-' + phenosFound + '-' + board.length + '-' + deck.length + '-' + startTime;
    // Simple hash from seed (deterministic, fast — not crypto)
    var h = 0;
    for (var i = 0; i < seed.length; i++) {
      h = ((h << 5) - h + seed.charCodeAt(i)) | 0;
    }
    // Convert to hex-like string, padded to 20 chars
    var hex = Math.abs(h).toString(16).padStart(8, '0');
    previewHash = (hex + hex + hex + hex).substring(0, 20);
    return previewHash;
  }

  // Map pheno count to growth progress (0.0 → 1.0)
  function getGrowthProgress() {
    if (phenosFound <= 0) return 0.05; // just the pot
    if (phenosFound <= 5) return 0.05 + (phenosFound / 5) * 0.25; // 0.05 → 0.3
    if (phenosFound <= 15) return 0.3 + ((phenosFound - 5) / 10) * 0.3; // 0.3 → 0.6
    if (phenosFound <= 30) return 0.6 + ((phenosFound - 15) / 15) * 0.3; // 0.6 → 0.9
    return 1.0; // full bloom
  }

  function getGrowthLabel() {
    var p = getGrowthProgress();
    if (p <= 0.1) return 'Seed';
    if (p <= 0.3) return 'Sprout';
    if (p <= 0.6) return 'Seedling';
    if (p <= 0.9) return 'Growing';
    return 'Full Bloom';
  }

  function updateFocusPlant() {
    var el = document.getElementById('focus-plant');
    if (!el) return;
    var hash = buildPreviewHash();
    var prog = getGrowthProgress();
    var label = getGrowthLabel();

    el.innerHTML = generatePlantSVG(hash, 70, prog) +
      '<div class="focus-plant-label">' + label + '</div>' +
      '<div class="focus-plant-stage">' + phenosFound + ' trios</div>';

    // Milestone at full bloom
    if (prog >= 1.0 && !milestoneShown) {
      milestoneShown = true;
      setTimeout(function() {
        document.getElementById('milestone-drop').classList.add('visible');
      }, 800);
      if (typeof gtag !== 'undefined') gtag('event', 'lucid_winds_bloom', { phenos: phenosFound, time: getTimeSec() });
    }
  }

  // ═══ PROCEDURAL PLANT GENERATOR ═══
  // Uses SHA-256 Attention Hash as DNA seed
  // Same hash = same plant always
  // Flat geometric SVG only — circles, rects, clean paths
  // Palette: #2D4221, #8FBC8F, #CC7156, #F4A460, #EAE0C8
  // ═══ MODULAR TRAIT BANK — SVG Plant Components ═══
  // ═══════════════════════════════════════════════════════════
  // PROCEDURAL PLANT ENGINE v2 — HIGH FIDELITY SVG
  // 16M+ unique combinations · Gradient rendering · Glow filters
  // Animated companions · Mutation system · Full hex entropy
  // ═══════════════════════════════════════════════════════════

  var _darkPlantBoost = false; // shared flag — set by generatePlantSVG, read by renderLeaves

  var PALETTE = {
    pine:'#3A5C2A', sage:'#8CB86E', terra:'#C4633A', sand:'#E8C07A', cream:'#F4EDDA',
    gold:'#D4B455', plum:'#7A5080', amber:'#D4A014', moss:'#5E8550', rust:'#A85520',
    slate:'#5E7275', rose:'#A87285', teal:'#4A8A78', copper:'#A87850', ash:'#959588',
    violet:'#8860A8'
  };
  var PAL_KEYS = ['pine','sage','terra','sand','cream','moss','slate','teal','copper','ash','plum','amber','rust','rose','violet','gold'];

  var STEM_COLORS = [
    {base:'#3A5C2A', light:'#5E8550'},  // 0: Forest Green (default)
    {base:'#3D4A2A', light:'#5A6B42'},  // 1: Dark Olive
    {base:'#5A6B58', light:'#7A8B72'},  // 2: Sage Gray
    {base:'#5A3E2B', light:'#8B6B4A'},  // 3: Warm Brown
    {base:'#5A2A2A', light:'#8B4A4A'},  // 4: Deep Burgundy
    {base:'#2A5A5A', light:'#4A8B7A'},  // 5: Teal Green
    {base:'#4A2A5A', light:'#7A5A8B'},  // 6: Purple Vine
    {base:'#8A8A7A', light:'#B0B0A0'},  // 7: Bone White
    {base:'#3A3A38', light:'#5A5A55'},  // 8: Charcoal
    {base:'#7A4A2A', light:'#A07040'},  // 9: Copper
    {base:'#1A5A3A', light:'#2A8A5A'},  // 10: Emerald
    {base:'#6A5A1A', light:'#9A8A3A'}   // 11: Amber
  ];

  // ── Micro hue-shift: vary a hex color by ±shift on each channel for organic variance ──
  function _hueShift(hex, seed, shift) {
    shift = shift || 8;
    var r = parseInt(hex.slice(1,3),16), g = parseInt(hex.slice(3,5),16), b = parseInt(hex.slice(5,7),16);
    var rng = ((seed * 1664525 + 1013904223) & 0xFFFFFF) / 0xFFFFFF;
    var dr = Math.round((rng - 0.5) * shift * 2);
    var dg = Math.round(((rng * 1.618) % 1 - 0.5) * shift * 1.4);
    var db = Math.round(((rng * 2.414) % 1 - 0.5) * shift);
    var clamp = function(v){ return Math.max(0,Math.min(255,v)); };
    var toHex = function(v){ return clamp(v).toString(16).padStart(2,'0'); };
    return '#' + toHex(r+dr) + toHex(g+dg) + toHex(b+db);
  }

  // ── Mutation color helpers ──
  function _toAlbino(hex) {
    if (!hex || hex.length < 7) return '#F0EBD8';
    var r = parseInt(hex.slice(1,3),16), g = parseInt(hex.slice(3,5),16), b = parseInt(hex.slice(5,7),16);
    r = Math.round(r * 0.15 + 240 * 0.85);
    g = Math.round(g * 0.15 + 235 * 0.85);
    b = Math.round(b * 0.15 + 216 * 0.85);
    return '#' + ((1<<24)+(r<<16)+(g<<8)+b).toString(16).slice(1);
  }
  function _toStone(hex) {
    if (!hex || hex.length < 7) return '#A09880';
    var r = parseInt(hex.slice(1,3),16), g = parseInt(hex.slice(3,5),16), b = parseInt(hex.slice(5,7),16);
    var gray = Math.round(r * 0.299 + g * 0.587 + b * 0.114);
    r = Math.round(gray * 0.6 + 160 * 0.4);
    g = Math.round(gray * 0.6 + 152 * 0.4);
    b = Math.round(gray * 0.6 + 128 * 0.4);
    return '#' + ((1<<24)+(r<<16)+(g<<8)+b).toString(16).slice(1);
  }
  function _toPorcelain(hex) {
    if (!hex || hex.length < 7) return '#F0EBD8';
    var r = parseInt(hex.slice(1,3),16), g = parseInt(hex.slice(3,5),16), b = parseInt(hex.slice(5,7),16);
    var lum = (r * 0.299 + g * 0.587 + b * 0.114) / 255;
    return lum > 0.45 ? '#F0EBD8' : '#234B8A';
  }
  function _toInk(hex) {
    if (!hex || hex.length < 7) return '#8A8A7A';
    var r = parseInt(hex.slice(1,3),16), g = parseInt(hex.slice(3,5),16), b = parseInt(hex.slice(5,7),16);
    var gray = Math.round(r * 0.299 + g * 0.587 + b * 0.114);
    var warm = Math.round(gray * 0.85 + 40);
    warm = Math.min(255, warm);
    return '#' + ((1<<24)+(warm<<16)+(Math.round(warm*0.97)<<8)+Math.round(warm*0.90)).toString(16).slice(1);
  }
  function _mutColor(hex, mutName) {
    if (mutName === 'Albino') return _toAlbino(hex);
    if (mutName === 'Fossil') return _toStone(hex);
    if (mutName === 'Porcelain') return _toPorcelain(hex);
    if (mutName === 'Ink Wash') return _toInk(hex);
    if (mutName === 'Neon') return '#1a1a2a';
    if (mutName === 'Silhouette') return '#0d100c';
    return hex;
  }

  // ── Gemini Micro-Texture System v1 — procedural surface detail ──
  // Single <path> per call using disconnected subpaths. Zero DOM bloat.
  // Styles: stipple (dots), crosshatch (diagonals), bark (wavy dashes), grain (verticals)
  function microTexture(x, y, w, h, seed, color, opacity, style) {
    var s = seed;
    var rand = function() { s = (s * 1103515245 + 12345) & 0x7fffffff; return s / 0x7fffffff; };
    var f = function(v) { return (Math.round(v * 10) / 10); };
    var d = '';

    if (style === 'stipple') {
      for (var i = 0; i < 12; i++) {
        d += 'M' + f(x + rand() * w) + ',' + f(y + rand() * h) + 'h.1';
      }
      return '<path d="' + d + '" stroke="' + color + '" stroke-opacity="' + f(opacity) + '" stroke-width="' + f(0.5 + rand() * 0.4) + '" stroke-linecap="round"/>';
    }
    if (style === 'crosshatch') {
      for (var i = 0; i < 5; i++) {
        var len = 2 + rand() * (w * 0.25);
        d += 'M' + f(x + rand() * w) + ',' + f(y + rand() * h) + 'l' + f(len) + ',' + f(len);
      }
      return '<path d="' + d + '" stroke="' + color + '" stroke-opacity="' + f(opacity) + '" stroke-width="0.4" fill="none"/>';
    }
    if (style === 'bark') {
      for (var i = 0; i < 8; i++) {
        var len = 3 + rand() * (w * 0.15);
        var arcY = (rand() > 0.5 ? 1 : -1) * (0.3 + rand() * 0.8);
        d += 'M' + f(x + rand() * w) + ',' + f(y + rand() * h) + 'q' + f(len / 2) + ',' + f(arcY) + ' ' + f(len) + ',0';
      }
      return '<path d="' + d + '" stroke="' + color + '" stroke-opacity="' + f(opacity) + '" stroke-width="0.6" fill="none"/>';
    }
    if (style === 'grain') {
      for (var i = 0; i < 10; i++) {
        var len = h * 0.15 + rand() * (h * 0.3);
        d += 'M' + f(x + rand() * w) + ',' + f(y + rand() * h) + 'v' + f(len);
      }
      return '<path d="' + d + '" stroke="' + color + '" stroke-opacity="' + f(opacity) + '" stroke-width="0.3" fill="none"/>';
    }
    return '';
  }
  var LEAF_PALS = ['pine','sage','moss','teal','plum','amber','slate','rose'];
  var BLOOM_PALS = ['gold','terra','plum','cream','rust','amber','rose','copper','violet','teal'];

  // ── SVG DEFS — injected once per plant ──
  function buildDefs(t, uid) {
    var d = '<defs>';
    var _mn = t.mutationName || 'None';
    var _colorMut = (_mn === 'Albino' || _mn === 'Fossil' || _mn === 'Porcelain' || _mn === 'Ink Wash' || _mn === 'Neon' || _mn === 'Silhouette');
    // Pot gradient
    var pc = PALETTE[t.potColor] || PALETTE.terra;
    if (_colorMut) pc = _mutColor(pc, _mn);
    d += '<linearGradient id="pg'+uid+'" x1="0" y1="0" x2="0" y2="1">';
    d += '<stop offset="0%" stop-color="'+pc+'" stop-opacity="1.0"/>';
    d += '<stop offset="100%" stop-color="'+pc+'" stop-opacity="0.85"/>';
    d += '</linearGradient>';
    // Pot rim highlight
    var _rimHL = _colorMut ? _mutColor('#EAE0C8', _mn) : '#EAE0C8';
    d += '<linearGradient id="pr'+uid+'" x1="0" y1="0" x2="1" y2="0">';
    d += '<stop offset="0%" stop-color="'+pc+'" stop-opacity="0.3"/>';
    d += '<stop offset="50%" stop-color="'+_rimHL+'" stop-opacity="0.2"/>';
    d += '<stop offset="100%" stop-color="'+pc+'" stop-opacity="0.3"/>';
    d += '</linearGradient>';
    // Stem gradient — color from STEM_COLORS[t.stemColor]
    var _sc = STEM_COLORS[t.stemColor] || STEM_COLORS[0];
    var _scBase = _colorMut ? _mutColor(_sc.base, _mn) : _sc.base;
    var _scLight = _colorMut ? _mutColor(_sc.light, _mn) : _sc.light;
    d += '<linearGradient id="sg'+uid+'" x1="0" y1="1" x2="0" y2="0">';
    d += '<stop offset="0%" stop-color="'+_scBase+'" stop-opacity="0.9"/>';
    d += '<stop offset="100%" stop-color="'+_scLight+'" stop-opacity="0.8"/>';
    d += '</linearGradient>';
    // Leaf gradients (2 variations)
    var lc1 = PALETTE[t.leafColors[0]] || PALETTE.sage;
    var lc2 = PALETTE[t.leafColors[1]] || PALETTE.pine;
    if (_colorMut) {
      // Silhouette: keep bloom color, but if no bloom keep lc1 normal
      if (_mn === 'Silhouette' && !t.hasFlower) {
        lc2 = _mutColor(lc2, _mn);
      } else if (_colorMut) {
        lc1 = _mutColor(lc1, _mn);
        lc2 = _mutColor(lc2, _mn);
      }
    }
    d += '<linearGradient id="lf1'+uid+'" x1="0" y1="0" x2="1" y2="1">';
    d += '<stop offset="0%" stop-color="'+lc1+'" stop-opacity="0.85"/>';
    d += '<stop offset="100%" stop-color="'+lc1+'" stop-opacity="0.5"/>';
    d += '</linearGradient>';
    d += '<linearGradient id="lf2'+uid+'" x1="1" y1="0" x2="0" y2="1">';
    d += '<stop offset="0%" stop-color="'+lc2+'" stop-opacity="0.85"/>';
    d += '<stop offset="100%" stop-color="'+lc2+'" stop-opacity="0.5"/>';
    d += '</linearGradient>';
    // Bloom radial gradient
    var bc = PALETTE[BLOOM_PALS[t.flower % BLOOM_PALS.length]] || PALETTE.gold;
    // Silhouette keeps bloom color as accent; others mutate it
    if (_colorMut && _mn !== 'Silhouette') bc = _mutColor(bc, _mn);
    d += '<radialGradient id="bg'+uid+'">';
    d += '<stop offset="0%" stop-color="'+bc+'" stop-opacity="0.9"/>';
    d += '<stop offset="80%" stop-color="'+bc+'" stop-opacity="0.5"/>';
    d += '<stop offset="100%" stop-color="'+bc+'" stop-opacity="0.15"/>';
    d += '</radialGradient>';
    // Glow filter — for rare traits
    d += '<filter id="gw'+uid+'" x="-50%" y="-50%" width="200%" height="200%">';
    d += '<feGaussianBlur stdDeviation="3" result="blur"/>';
    d += '<feMerge><feMergeNode in="blur"/><feMergeNode in="SourceGraphic"/></feMerge>';
    d += '</filter>';
    // Intense glow — for mutations
    d += '<filter id="gi'+uid+'" x="-50%" y="-50%" width="200%" height="200%">';
    d += '<feGaussianBlur stdDeviation="5" result="blur"/>';
    d += '<feMerge><feMergeNode in="blur"/><feMergeNode in="blur"/><feMergeNode in="SourceGraphic"/></feMerge>';
    d += '</filter>';
    // ── Phase 23: Drop-shadow filter (leaf depth separator) ──
    d += '<filter id="ds'+uid+'" x="-20%" y="-20%" width="140%" height="140%">';
    d += '<feDropShadow dx="1.4" dy="1.4" stdDeviation="0.8" flood-color="#0a0d08" flood-opacity="0.55"/>';
    d += '</filter>';
    // ── Phase 23: Glow core filter (bloom luminance / Obsidian core) ──
    d += '<filter id="gc'+uid+'" x="-60%" y="-60%" width="220%" height="220%">';
    d += '<feGaussianBlur stdDeviation="1.8" result="glow"/>';
    d += '<feMerge><feMergeNode in="glow"/><feMergeNode in="glow"/><feMergeNode in="SourceGraphic"/></feMerge>';
    d += '</filter>';
    // ── Phase 23: Mandala halo gradient ──
    d += '<radialGradient id="mh'+uid+'" cx="50%" cy="50%">';
    d += '<stop offset="0%" stop-color="#C8A84B" stop-opacity="0.18"/>';
    d += '<stop offset="55%" stop-color="#8FAF5B" stop-opacity="0.08"/>';
    d += '<stop offset="100%" stop-color="#C8A84B" stop-opacity="0"/>';
    d += '</radialGradient>';
    // Golden pot radial
    d += '<radialGradient id="gp'+uid+'">';
    d += '<stop offset="0%" stop-color="#C8A84B" stop-opacity="0.35"/>';
    d += '<stop offset="100%" stop-color="#C8A84B" stop-opacity="0"/>';
    d += '</radialGradient>';
    // Glass gradient for glass-stem mutation
    d += '<linearGradient id="gl'+uid+'" x1="0" y1="1" x2="0" y2="0">';
    d += '<stop offset="0%" stop-color="#5b8fb9" stop-opacity="0.25"/>';
    d += '<stop offset="50%" stop-color="#EAE0C8" stop-opacity="0.12"/>';
    d += '<stop offset="100%" stop-color="#5b8fb9" stop-opacity="0.2"/>';
    d += '</linearGradient>';
    // ── Phase 3 Mythic Filters ──
    if(t.mythicName==='Woolly Mammoth'){
      d+='<radialGradient id="bio_bg_'+uid+'" cx="50%" cy="50%">';
      d+='<stop offset="0%" stop-color="#00e5cc" stop-opacity="0.2"/>';
      d+='<stop offset="55%" stop-color="#006b6b" stop-opacity="0.09"/>';
      d+='<stop offset="100%" stop-color="#00e5cc" stop-opacity="0"/>';
      d+='</radialGradient>';
      d+='<filter id="bio_f_'+uid+'" x="-40%" y="-40%" width="180%" height="180%" color-interpolation-filters="sRGB">';
      d+='<feGaussianBlur stdDeviation="5" result="blur"/>';
      d+='<feTurbulence type="fractalNoise" baseFrequency="0.018" numOctaves="2" seed="7" result="noise"/>';
      d+='<feDisplacementMap in="blur" in2="noise" scale="9" xChannelSelector="R" yChannelSelector="G" result="warped"/>';
      d+='<feMerge><feMergeNode in="warped"/><feMergeNode in="SourceGraphic"/></feMerge>';
      d+='</filter>';
    }
    if(t.mythicName==='Great Blue Heron'){
      var _swSeed=(parseInt(uid,16)%97)+2;
      d+='<filter id="sw_f_'+uid+'" x="-25%" y="-5%" width="150%" height="110%">';
      d+='<feTurbulence type="fractalNoise" baseFrequency="0.68" numOctaves="3" seed="'+_swSeed+'" result="noise"/>';
      d+='<feColorMatrix type="saturate" values="0" in="noise" result="grey"/>';
      d+='<feBlend in="SourceGraphic" in2="grey" mode="overlay" result="blend"/>';
      d+='<feComposite in="blend" in2="SourceAlpha" operator="in"/>';
      d+='</filter>';
    }
    d += '</defs>';
    return d;
  }

