    if (t.breedLayers && t.breedLayers.vigorBand) svg += renderVigorBand(t, uid, visibleTop);
    if (t.compostLayers && t.compostLayers.nutrientVeins) svg += renderNutrientVeins(uid, visibleTop, t.compostLayers.nutrientVeins);

