    if (t.breedLayers && t.breedLayers.rootTendrils) svg += renderRootTendrils(uid);
    if (t.compostLayers && t.compostLayers.decomposerRings) svg += renderDecomposerRings(uid);
    if (t.compostLayers && t.compostLayers.phoenixAsh) svg += renderPhoenixAsh(uid, t.compostLayers.phoenixAsh);
