          s += '<path d="M'+ox+','+ly+' Q'+_fCX.toFixed(1)+','+_fCY.toFixed(1)+' '+_fTX.toFixed(1)+','+_fTY.toFixed(1)+'"'
             + ' fill="none" stroke="rgba(240,235,216,0.3)" stroke-width="0.3" stroke-linecap="round"/>';
