                _ncvD = 'M'+_cv1x.toFixed(1)+','+_cv1y.toFixed(1)+' C'+(ox + side*nLen*0.22).toFixed(1)+','+(ly-nLen*0.30).toFixed(1)+' '+_cv2x.toFixed(1)+','+(_cv2y+nLen*0.08).toFixed(1)+' '+(nx - Math.sin(na)*nLen*0.06*side).toFixed(1)+','+(ny + Math.cos(na)*nLen*0.06).toFixed(1);
