          s += '<path d="'+_vtUD+'" fill="'+fill+'" opacity="'+Math.max(0.92, op)+'" filter="url(#ds'+uid+')"/>';
          // Inner red-pink tint — deeper color
          s += '<path d="'+_vtUD+'" fill="'+_hueShift(_vtCol3, i*23, 15)+'" opacity="'+(op*0.25).toFixed(2)+'"/>';
          // Digestive gland texture — small dots scattered inside upper lobe
          for (var _vtg = 0; _vtg < 6; _vtg++) {
            var _vtgA = Math.PI * (0.25 + _vtg * 0.1);
            var _vtgR = _vtW * (0.2 + (_vtg % 3) * 0.08);
            var _vtgX = _vtCx + Math.cos(_vtgA) * _vtgR * side;
            var _vtgY = _vtCy - Math.sin(_vtgA) * _vtgR * 0.8;
            s += '<circle cx="'+_vtgX.toFixed(1)+'" cy="'+_vtgY.toFixed(1)+'" r="0.2" fill="'+_vtCol2+'" opacity="'+(op*0.25).toFixed(2)+'"/>';
          }
          // Lower lobe — with depth shadow
          var _vtLD = 'M'+(_vtCx-side*_vtW*0.52).toFixed(1)+','+_vtCy.toFixed(1)+' A'+(_vtW*0.52).toFixed(1)+','+(_vtH*0.6).toFixed(1)+' 0 0,0 '+(_vtCx+side*_vtW*0.52).toFixed(1)+','+_vtCy.toFixed(1)+' Z';
          s += '<path d="'+_vtLD+'" fill="none" stroke="#1a1d18" stroke-width="0.5" opacity="'+(op*0.25).toFixed(2)+'"/>';
          s += '<path d="'+_vtLD+'" fill="'+fill+'" opacity="'+(op*0.88).toFixed(2)+'" filter="url(#ds'+uid+')"/>';
          s += '<path d="'+_vtLD+'" fill="'+_vtCol2+'" opacity="'+(op*0.3).toFixed(2)+'"/>';
          // TEETH — 7 sharp interlocking spikes along upper lobe edge
          for (var _vtt = 0; _vtt < 7; _vtt++) {
            var _vttA = Math.PI * (0.15 + _vtt * 0.1);
            var _vttBx = _vtCx + Math.cos(_vttA) * _vtW * 0.52 * side;
            var _vttBy = _vtCy - Math.sin(_vttA) * _vtH * 0.72;
            var _vttTx = _vtCx + Math.cos(_vttA) * _vtW * 0.72 * side;
            var _vttTy = _vtCy - Math.sin(_vttA) * _vtH * 0.95;
            // Tooth body — tapered triangle
            s += '<path d="M'+_vttBx.toFixed(1)+','+_vttBy.toFixed(1)+' L'+_vttTx.toFixed(1)+','+_vttTy.toFixed(1)+' L'+(_vttBx+Math.cos(_vttA+0.15)*_vtW*0.06*side).toFixed(1)+','+(_vttBy-Math.sin(_vttA+0.15)*_vtH*0.06).toFixed(1)+'"'
               + ' fill="rgba(240,235,216,0.3)" opacity="'+(op*0.6).toFixed(2)+'"/>';
            s += '<line x1="'+_vttBx.toFixed(1)+'" y1="'+_vttBy.toFixed(1)+'" x2="'+_vttTx.toFixed(1)+'" y2="'+_vttTy.toFixed(1)+'"'
               + ' stroke="'+shiftedDark+'" stroke-width="0.4" opacity="'+(op*0.55).toFixed(2)+'" stroke-linecap="round"/>';
          }
