        s += '<path d="M'+fx+','+fy+' Q'+(fx-fs)+','+(fy-fs*0.5)+' '+(fx-fs*0.8)+','+(fy-fs*1.8)+' Q'+fx+','+(fy-fs*1.2)+' '+fx+','+fy+'" fill="'+PALETTE.sage+'" stroke="'+PALETTE.pine+'" stroke-width="1" opacity="'+(0.9*bloomOp)+'"/>';
