        s += '<path d="M'+fx+','+(fy-fs*0.2)+' C'+(fx-fs*0.9)+','+(fy-fs*1.1)+' '+(fx-fs*1.25)+','+(fy+fs*0.15)+' '+(fx-fs*0.35)+','+(fy+fs*0.55)+' C'+(fx-fs*0.05)+','+(fy+fs*0.2)+' '+(fx-fs*0.1)+','+(fy-fs*0.05)+' '+fx+','+(fy-fs*0.2)+' Z" fill="'+fc+'" opacity="'+(0.68*bloomOp)+'"/>';
