          // Outer ember glow
          s += '<ellipse cx="'+fx+'" cy="'+(fy + fs*0.05)+'" rx="'+(_flBaseR*0.7)+'" ry="'+(_flBaseR*0.35)+'"'
             + ' fill="'+_flInner+'" opacity="'+(0.5*bloomOp)+'" filter="url(#gc'+uid+')"/>';
          // Mid ember
          s += '<ellipse cx="'+fx+'" cy="'+(fy + fs*0.02)+'" rx="'+(_flBaseR*0.45)+'" ry="'+(_flBaseR*0.22)+'"'
             + ' fill="'+_flHot+'" opacity="'+(0.7*bloomOp)+'"/>';
          // White-hot center
          s += '<ellipse cx="'+fx+'" cy="'+fy+'" rx="'+(_flBaseR*0.25)+'" ry="'+(_flBaseR*0.12)+'"'
             + ' fill="#FFF8E0" opacity="'+(0.85*bloomOp)+'"/>';
          // Specular spark
          s += '<circle cx="'+(fx - _flBaseR*0.08)+'" cy="'+(fy - _flBaseR*0.03)+'" r="'+(_flBaseR*0.06)+'"'
