          s += '<ellipse cx="'+(fx+fs*0.03)+'" cy="'+(fy+fs*0.06)+'" rx="'+(_viR*0.8)+'" ry="'+(_viR*0.7)+'"'
             + ' fill="rgba(0,0,0,0.1)" opacity="'+bloomOp+'"/>';

