          var _atTopY = _atOy;
          var _atBotY = _atTopY + _atH;

          // ── ARCHING STEM — 180° bend from bloom anchor to flower ──
          // Curves up from fx,fy then arches right and down to the trumpet neck
          s += '<path d="M'+fx+','+fy
             + ' C'+(fx + fs*0.2)+','+(fy - fs*0.8)+' '+(fx + fs*1.0)+','+(fy - fs*0.6)+' '+_atOx+','+_atOy+'"'
             + ' fill="none" stroke="#5E8550" stroke-width="'+(fs*0.08)+'" stroke-linecap="round" opacity="'+(0.85*bloomOp)+'"/>';
          // Stem highlight
          s += '<path d="M'+fx+','+fy
             + ' C'+(fx + fs*0.18)+','+(fy - fs*0.78)+' '+(fx + fs*0.98)+','+(fy - fs*0.58)+' '+_atOx+','+_atOy+'"'
             + ' fill="none" stroke="rgba(255,255,255,0.1)" stroke-width="'+(fs*0.03)+'" opacity="'+bloomOp+'"/>';

