            var cxTy = _atOy + Math.sin(cxAng) * fs * 0.08 - fs * 0.05;
            s += '<line x1="'+_atOx+'" y1="'+(_atOy - fs*0.03)+'" x2="'+cxTx.toFixed(1)+'" y2="'+cxTy.toFixed(1)+'"'
