          s += '<path d="M'+(_atOx - _atNeckW)+','+_atTopY
             + ' C'+(_atOx - _atNeckW*1.15)+','+(_atTopY + _atH*0.3)+' '+(_atOx - _atOpenW*0.7)+','+(_atTopY + _atH*0.65)+' '+(_atOx - _atOpenW)+','+_atBotY.toFixed(1)
             + ' L'+(_atOx + _atOpenW)+','+_atBotY.toFixed(1)
             + ' C'+(_atOx + _atOpenW*0.7)+','+(_atTopY + _atH*0.65)+' '+(_atOx + _atNeckW*1.15)+','+(_atTopY + _atH*0.3)+' '+(_atOx + _atNeckW)+','+_atTopY+' Z"'
             + ' fill="'+fc+'" opacity="'+(0.9*bloomOp)+'" stroke="rgba(0,0,0,0.06)" stroke-width="0.15"/>';

          // ── INTERIOR SHADOW ──
