              var pTipY = hp.y + Math.sin(pAng) * hfr;
              var pW = hfr * 0.45;

              // Petal — rounded teardrop
              var pcp1x = hp.x + Math.cos(pAng) * hfr * 0.3 + Math.cos(perpP) * pW * 0.55;
              var pcp1y = hp.y + Math.sin(pAng) * hfr * 0.3 + Math.sin(perpP) * pW * 0.55;
              var pcp2x = hp.x + Math.cos(pAng) * hfr * 0.3 - Math.cos(perpP) * pW * 0.55;
              var pcp2y = hp.y + Math.sin(pAng) * hfr * 0.3 - Math.sin(perpP) * pW * 0.55;

              s += '<path d="M'+hp.x.toFixed(1)+','+hp.y.toFixed(1)
                 + ' C'+pcp1x.toFixed(1)+','+pcp1y.toFixed(1)+' '+(pTipX + Math.cos(perpP)*pW*0.15).toFixed(1)+','+(pTipY + Math.sin(perpP)*pW*0.15).toFixed(1)+' '+pTipX.toFixed(1)+','+pTipY.toFixed(1)
                 + ' C'+(pTipX - Math.cos(perpP)*pW*0.15).toFixed(1)+','+(pTipY - Math.sin(perpP)*pW*0.15).toFixed(1)+' '+pcp2x.toFixed(1)+','+pcp2y.toFixed(1)+' '+hp.x.toFixed(1)+','+hp.y.toFixed(1)+' Z"'
