            var oL = fx + Math.cos(perpO) * oBaseW;
            var oLy = _thBaseY + Math.sin(perpO) * oBaseW;
            var oR = fx - Math.cos(perpO) * oBaseW;
            var oRy = _thBaseY - Math.sin(perpO) * oBaseW;

            s += '<path d="M'+oL.toFixed(1)+','+oLy.toFixed(1)+' L'+oTipX.toFixed(1)+','+oTipY.toFixed(1)+' L'+oR.toFixed(1)+','+oRy.toFixed(1)+' Z"'
               + ' fill="#5A6B40" opacity="'+(0.95*bloomOp)+'" stroke="#3A4A28" stroke-width="0.2"/>';
