          // ── ARTICHOKE BODY — dense overlapping scale dome ──
          // Solid dark base shape
          var _bodyTopY = _thBaseY - _thBodyH;
          s += '<path d="M'+(fx - _thW*0.5)+','+_thBaseY
             + ' C'+(fx - _thW*0.6)+','+(_thBaseY - _thBodyH*0.5)+' '+(fx - _thW*0.35)+','+_bodyTopY.toFixed(1)+' '+fx+','+(_bodyTopY - fs*0.1).toFixed(1)
             + ' C'+(fx + _thW*0.35)+','+_bodyTopY.toFixed(1)+' '+(fx + _thW*0.6)+','+(_thBaseY - _thBodyH*0.5)+' '+(fx + _thW*0.5)+','+_thBaseY+' Z"'
             + ' fill="#4A5A35" opacity="'+(0.95*bloomOp)+'"/>';

