          for (var ri = 0; ri < 4; ri++) {
            var rowY = _thBaseY - _thBodyH * (ri * 0.22 + 0.15);
            var rowW = _thW * (0.5 - ri * 0.07);
            var scalesInRow = 5 - ri; // fewer scales as it narrows
            for (var si = 0; si < scalesInRow; si++) {
              var sFrac = (si / (scalesInRow - 1)) - 0.5; // -0.5 to 0.5
              var scX = fx + sFrac * rowW * 1.6;
              var scW = rowW * 0.35;
              var scH = _thBodyH * 0.12;
              // Scale crescent
              s += '<path d="M'+(scX - scW).toFixed(1)+','+rowY.toFixed(1)
                 + ' Q'+scX.toFixed(1)+','+(rowY - scH).toFixed(1)+' '+(scX + scW).toFixed(1)+','+rowY.toFixed(1)+'"'
                 + ' fill="none" stroke="#7A8F5A" stroke-width="'+(fs*0.07)+'" stroke-linecap="round" opacity="'+(0.85*bloomOp)+'"/>';
              // Scale highlight — upper edge
              s += '<path d="M'+(scX - scW*0.8).toFixed(1)+','+(rowY - scH*0.15).toFixed(1)
                 + ' Q'+scX.toFixed(1)+','+(rowY - scH*0.85).toFixed(1)+' '+(scX + scW*0.8).toFixed(1)+','+(rowY - scH*0.15).toFixed(1)+'"'
                 + ' fill="none" stroke="rgba(255,255,255,0.12)" stroke-width="0.25" opacity="'+bloomOp+'"/>';
            }
          }

