          s += '<ellipse cx="'+(fx - _thW*0.1)+'" cy="'+(_bodyTopY + _thBodyH*0.2).toFixed(1)+'" rx="'+(_thW*0.25)+'" ry="'+(_thBodyH*0.15)+'"'
             + ' fill="rgba(255,255,255,0.08)" opacity="'+bloomOp+'"/>';

