          s += '<ellipse cx="'+fx+'" cy="'+(_bristleBase - _thBristleH*0.4).toFixed(1)+'" rx="'+(_thW*0.5)+'" ry="'+(_thBristleH*0.3)+'"'
             + ' fill="'+fc+'" opacity="'+(0.08*bloomOp)+'"/>';

