          s += '<circle cx="'+fx+'" cy="'+fy+'" r="'+(fs*0.06)+'" fill="'+PALETTE.gold+'" opacity="'+(0.85*bloomOp)+'"/>';
          s += '<circle cx="'+(fx-fs*0.02)+'" cy="'+(fy-fs*0.02)+'" r="'+(fs*0.025)+'" fill="rgba(255,255,255,0.4)" opacity="'+bloomOp+'"/>';
