            var ocp1x = fx + Math.cos(oAng) * oReach * 0.25 + Math.cos(perpO) * oPW * 0.65;
            var ocp1y = fy + Math.sin(oAng) * oReach * 0.25 + Math.sin(perpO) * oPW * 0.65;
