        s += '<line x1="35" y1="76" x2="35" y2="'+(78-t.stemHeight*0.8)+'" stroke="#C8A84B" stroke-width="0.3" opacity="0.2" filter="url(#gw'+uid+')"/>';
        // mutation label removed
