  // ── ANCIENT RUNE FIELD renderer ──
  function renderRuneField(t, uid) {
    var GLYPHS=['☽','⊕','✦','⚘','⌖','⍟','✶'];
    var TV=[t.pot%16,t.stem%16,t.leafType%16,t.leafCount,(t.flower||0)%16,t.aura%19,t.base%30];
    var s = '';
    for(var ri=0;ri<7;ri++){
      var rx=(10+(TV[ri]/15)*52).toFixed(1);
      var ry=(15+(TV[(ri+3)%7]/15)*56).toFixed(1);
      var rdur=(5.2+ri*0.7)+'s', rbeg=(ri*0.9)+'s';
      s += '<text x="'+rx+'" y="'+ry+'" text-anchor="middle" font-size="4.5" fill="url(#bg'+uid+')" font-family="serif" opacity="0">';
      s += GLYPHS[ri];
      s += '<animateTransform attributeName="transform" type="translate" values="0,0;0,-90" dur="'+rdur+'" begin="'+rbeg+'" repeatCount="indefinite" calcMode="linear"/>';
      s += '<animate attributeName="opacity" values="0;0.58;0.58;0" keyTimes="0;0.14;0.76;1" dur="'+rdur+'" begin="'+rbeg+'" repeatCount="indefinite"/>';
      s += '</text>';
    }
    return s;
  }

  // ── STORM WRAITH renderer ──
  function renderStormWraith(t, uid) {
    var s = '';
    for(var ri=0;ri<7;ri++){
      var rxs=4+ri*9, rys=-14+(ri%3)*5;
      var rdur=(0.72+ri*0.11)+'s', rbeg=(ri*0.21)+'s';
      s += '<line x1="'+rxs+'" y1="'+rys+'" x2="'+(rxs+10)+'" y2="'+(rys+15)+'" stroke="#a8c8e8" stroke-width="0.32" stroke-linecap="round" opacity="0">';
      s += '<animateTransform attributeName="transform" type="translate" values="0,0;-10,96" dur="'+rdur+'" begin="'+rbeg+'" repeatCount="indefinite" calcMode="linear"/>';
      s += '<animate attributeName="opacity" values="0;0.19;0.19;0" dur="'+rdur+'" begin="'+rbeg+'" repeatCount="indefinite"/>';
      s += '</line>';
    }
    s += '<ellipse cx="35" cy="47" rx="28" ry="36" fill="#a8c0ff" opacity="0">';
    s += '<animate attributeName="opacity" values="0;0;0;0;0;0.08;0;0;0;0;0;0.05;0;0;0;0;0;0.07;0;0" dur="10s" repeatCount="indefinite" calcMode="discrete"/>';
    s += '</ellipse>';
    s += '<rect x="0" y="0" width="4" height="95" fill="rgba(168,200,232,0.07)" filter="url(#sw_f_'+uid+')"/>';
    return s;
  }

