        s += '<path d="M58.2,13.8 C60.0,11.8 61.8,10.6 64.3,9.9" fill="none" stroke="#8B7B9B" stroke-width="0.7" stroke-linecap="round"/>';
        s += '<path d="M61.0,17.0 C63.6,15.9 65.6,15.7 67.6,16.3" fill="none" stroke="#8B7B9B" stroke-width="0.7" stroke-linecap="round"/>';
        s += '<ellipse cx="43.9" cy="11.2" rx="1.5" ry="1.3" fill="#EAE0C8"/>';
        s += '<circle cx="43.9" cy="11.2" r="0.62" fill="#C8A84B"/>';
