        s += '<ellipse cx="49.2" cy="7.8" rx="1.35" ry="1.2" fill="#EAE0C8"/>';
        s += '<circle cx="49.2" cy="7.8" r="0.56" fill="#C8A84B"/>';
        s += '<circle cx="49.3" cy="7.8" r="0.22" fill="#1A1420"/>';
        s += '<ellipse cx="55.6" cy="6.9" rx="1.45" ry="1.28" fill="#EAE0C8"/>';
