  // ═══ PROCEDURAL COLLECTIBLE NAMING (set-103: 444×437 = 194,028 combos) ═══
  var NAME_ADJ = (window._LW_BANKS && window._LW_BANKS.NAME_ADJ) ? window._LW_BANKS.NAME_ADJ : [];
  var NAME_NOUN = (window._LW_BANKS && window._LW_BANKS.NAME_NOUN) ? window._LW_BANKS.NAME_NOUN : [];

  // ═══ NAME_REALM — Third component: "The [Adj] [Noun] of [Realm]" ═══
  // Forces, states, elements, atmospheres, temporal concepts, mythic resonance
  // Cross-checked against NAME_ADJ and NAME_NOUN for zero stem overlap
  var NAME_REALM = (window._LW_BANKS && window._LW_BANKS.NAME_REALM) ? window._LW_BANKS.NAME_REALM : [];

  function getPlantName(hash) {
    var t = hashToTraits(hash);
    var h = (hash || '').toLowerCase();
    while (h.length < 64) h += '0';

    // Use 3-hex-char windows for distribution across 444/437 entries (0-4095 range)
    var adjIdx = (parseInt(h[22]+h[23]+h[24], 16) || 0) % NAME_ADJ.length;
    var nounIdx = (parseInt(h[32]+h[33]+h[34], 16) || 0) % NAME_NOUN.length;

    var adj = NAME_ADJ[adjIdx];
    var noun = NAME_NOUN[nounIdx];

    var TITLES_MYTHIC = {
      'The Toad':             'of the Toad',
      'The Phoenix':         'of the Phoenix',
      'Garden Spider':        'of the Spider',
      'Woolly Mammoth': 'of the Mammoth',
      'Raccoon':   'of the Raccoon',
      'Great Blue Heron':         'of the Heron',
      'The Beholder':         'of the Beholder'  // set-103-8
    };

    var name = 'The ' + adj + ' ' + noun;

    // Mythic suffix
    if (t.mythicName !== 'None' && TITLES_MYTHIC[t.mythicName]) {
      name += ' ' + TITLES_MYTHIC[t.mythicName];
    }

    return name;
  }

  // ═══ NAMEPLATE — structured HTML for plant names ═══
  // Splits "The Adjective Noun of the Mythic" into styled parts
  function buildNameplate(hash) {
    var t = hashToTraits(hash);
    var h = (hash || '').toLowerCase();
    while (h.length < 64) h += '0';
    var adjIdx = (parseInt(h[22]+h[23]+h[24], 16) || 0) % NAME_ADJ.length;
    var nounIdx = (parseInt(h[32]+h[33]+h[34], 16) || 0) % NAME_NOUN.length;
    var adj = NAME_ADJ[adjIdx];
    var noun = NAME_NOUN[nounIdx];

    var TITLES_MYTHIC = {
      'The Toad':'of the Toad','The Phoenix':'of the Phoenix',
      'Garden Spider':'of the Spider','Woolly Mammoth':'of the Mammoth',
      'Raccoon':'of the Raccoon','Great Blue Heron':'of the Heron',
      'The Beholder':'of the Beholder'
    };
    var title = (t.mythicName !== 'None' && TITLES_MYTHIC[t.mythicName]) ? TITLES_MYTHIC[t.mythicName] : '';

    return '<span class="np-top">The ' + adj + '</span>'
      + '<span class="np-main">' + noun + '</span>'
      + (title ? '<span class="np-title">' + title + '</span>' : '');
  }
  window.buildNameplate = buildNameplate;

  // ═══ REALM — third name component ("of [Realm]") ═══
  function getPlantRealm(hash) {
    var h = (hash || '').toLowerCase();
    while (h.length < 64) h += '0';
    var t = hashToTraits(hash);

    // Mythic plants get their mythic title instead of realm
    var TITLES_MYTHIC = {
      'The Toad':             'of the Toad',
      'The Phoenix':         'of the Phoenix',
      'Garden Spider':        'of the Spider',
      'Woolly Mammoth': 'of the Mammoth',
      'Raccoon':   'of the Raccoon',
      'Great Blue Heron':         'of the Heron',
      'The Beholder':         'of the Beholder'
    };
    if (t.mythicName !== 'None' && TITLES_MYTHIC[t.mythicName]) {
      return TITLES_MYTHIC[t.mythicName];
    }

    // Use h[42-44] for realm index (independent of adj h[22-24] and noun h[32-34])
    var realmIdx = (parseInt(h[42]+h[43]+h[44], 16) || 0) % NAME_REALM.length;
    return 'of ' + NAME_REALM[realmIdx];
  }
  window.getPlantRealm = getPlantRealm;

  // ═══ PROCEDURAL HAIKU (set-103: 211×216×216 = 9,844,416 combinations) ═══
  var HAIKU_A = (window._LW_BANKS && window._LW_BANKS.HAIKU_A) ? window._LW_BANKS.HAIKU_A : [];
  var HAIKU_B = (window._LW_BANKS && window._LW_BANKS.HAIKU_B) ? window._LW_BANKS.HAIKU_B : [];
  var HAIKU_C = (window._LW_BANKS && window._LW_BANKS.HAIKU_C) ? window._LW_BANKS.HAIKU_C : [];

  // ═══ HAIKU ENGINE v4 — Gemini ear-checked banks + Director verified ═══
