  // ═══════════════════════════════════════════════════════════════
  // P5 — AMBIENT RAINSTORM ENGINE
  // ═══════════════════════════════════════════════════════════════
  var _rainCanvas = null, _rainCtx = null, _rainDrops = [], _rainRAF = null, _rainActive = false;

  function _initRain() {
    if (_rainCanvas) return;
    _rainCanvas = document.createElement('canvas');
    _rainCanvas.id = 'rain-canvas';
    document.body.appendChild(_rainCanvas);
    _rainCtx = _rainCanvas.getContext('2d');
    _resizeRain();
    window.addEventListener('resize', _resizeRain);
  }

  function _resizeRain() {
    if (!_rainCanvas) return;
    _rainCanvas.width  = window.innerWidth;
    _rainCanvas.height = window.innerHeight;
    _rainDrops = [];
    var count = Math.floor(_rainCanvas.width / (window._perfLite ? 16 : 8));
    for (var i = 0; i < count; i++) {
      _rainDrops.push({
        x: Math.random() * _rainCanvas.width,
        y: Math.random() * _rainCanvas.height,
        len: 8 + Math.random() * 14,
        speed: 2.8 + Math.random() * 3.5,
        op: 0.08 + Math.random() * 0.18
      });
    }
  }

  function _rainTick() {
    if (!_rainActive) return;
    var c = _rainCtx, w = _rainCanvas.width, h = _rainCanvas.height;
    c.clearRect(0, 0, w, h);
    c.strokeStyle = '#90C8E0';
    c.lineWidth = 0.7;
    _rainDrops.forEach(function(d) {
      c.globalAlpha = d.op;
      c.beginPath();
      c.moveTo(d.x, d.y);
      c.lineTo(d.x - d.len * 0.18, d.y + d.len);
      c.stroke();
      d.y += d.speed;
      if (d.y > h + d.len) { d.y = -d.len; d.x = Math.random() * w; }
    });
    c.globalAlpha = 1;
    _rainRAF = requestAnimationFrame(_rainTick);
  }

  function startRain() {
    _initRain();
    _rainActive = true;
    _rainCanvas.classList.remove('hidden');
    _rainTick();
  }

  function stopRain() {
    _rainActive = false;
    if (_rainRAF) cancelAnimationFrame(_rainRAF);
    if (_rainCanvas) _rainCanvas.classList.add('hidden');
  }

  window.startRain = startRain;
  window.stopRain = stopRain;

  window.toggleRain = function() {
    if (_rainActive) {
      stopRain();
      localStorage.setItem('sws_rain', '');
    } else {
      startRain();
      localStorage.setItem('sws_rain', '1');
    }
  };

