  // ── Phase 14: Cinematic Discovery Overlay ───────────────────────────────────────────
  // set-81: wrapped in _queueOverlay — serialized with triggerCinematicReveal.
  // Collect path uses _fadeOverlayOut (200ms kinetic close) then _releaseOverlay.
  function _showDiscoveryOverlay(seedHash, collectCallback) {
    _queueOverlay(function() {
      var ov = document.getElementById('discovery-overlay');
      if (!ov) {
        ov = document.createElement('div');
        ov.id = 'discovery-overlay';
        document.body.appendChild(ov);
      }

      var pColors = [
        'rgba(122,179,86,0.75)','rgba(212,180,85,0.65)',
        'rgba(240,235,216,0.5)','rgba(94,133,80,0.8)','rgba(140,184,110,0.6)'
      ];
      var parts = '';
      for (var p = 0; p < 18; p++) {
        parts += '<div class="disc-particle" style="'
          + 'left:' + (12 + (p*41)%76) + '%;top:' + (8 + (p*57)%84) + '%;'
          + 'width:' + (2+(p%5)) + 'px;height:' + (2+(p%5)) + 'px;'
          + 'background:' + pColors[p%5] + ';'
          + '--dur:' + (2.2+(p%6)*0.45).toFixed(1) + 's;'
          + '--del:' + ((p*28)%280/100).toFixed(2) + 's;'
          + '--dy:' + (-(35+(p*13)%60)) + 'px;'
          + '--dx:' + (((p*7)%15-7)*8) + 'px;"></div>';
      }

      var plantSVG = '';
      if (typeof generatePlantSVG === 'function') {
        try { plantSVG = generatePlantSVG(seedHash, 170, 1.0); } catch(e) {}
      }
      if (!plantSVG && typeof buildPlantSVG === 'function') {
        try { plantSVG = buildPlantSVG(seedHash); } catch(e) {}
      }

      var plantName=''; try{if(typeof getPlantName==='function') plantName=getPlantName(seedHash);}catch(e){}
      var traits='';    try{if(typeof getTraitSummary==='function') traits=getTraitSummary(seedHash);}catch(e){}
      var hk={line1:'',line2:'',line3:''};
                        try{if(typeof getHaiku==='function') hk=getHaiku(seedHash);}catch(e){}
      var hs = seedHash.length>=16 ? seedHash.slice(0,8)+'…'+seedHash.slice(-6) : seedHash;

      ov.innerHTML = parts
        + '<div class="disc-banner">🧬 NEW CROSS-BREED DISCOVERED!</div>'
        + '<div class="disc-plant-wrap">' + plantSVG + '</div>'
        + (plantName ? '<div class="disc-name">' + plantName + '</div>' : '')
        + '<div class="disc-hash">' + hs + '</div>'
        + (traits ? '<div class="disc-traits">' + traits + '</div>' : '')
        + (hk.line1 ? '<div class="disc-haiku">' + hk.line1 + '<br>' + hk.line2 + '<br>' + hk.line3 + '</div>' : '')
        + '<button class="disc-collect-btn" id="disc-collect-btn">✦ COLLECT SPECIMEN ✦</button>';

      _haptic('bloom'); // Phase 26: organic triple-pulse — cross-breed discovery
      ov.classList.add('active');

      var btn = document.getElementById('disc-collect-btn');
      if (btn) {
        btn.addEventListener('click', function handler() {
          btn.removeEventListener('click', handler);
          // set-81: kinetic 200ms fade-out before class removal + queue release
          _fadeOverlayOut(ov, 'active', function() {
            _haptic('sync'); // double-pulse — asset secured
            if (typeof collectCallback === 'function') collectCallback();
          });
        });
      }
    }); // end _queueOverlay
  }

  function _buildDNASpliceOverlay() {
    if (document.getElementById('dna-splice-overlay')) return;
    var el = document.createElement('div');
    el.id = 'dna-splice-overlay';
    // SVG helix
    var svgH = '<svg width="60" height="80" viewBox="0 0 60 80" xmlns="http://www.w3.org/2000/svg">';
    svgH += '<style>';
    svgH += '.dna-sa{animation:helixA 1.2s ease-in-out infinite}';
    svgH += '.dna-sb{animation:helixB 1.2s ease-in-out infinite}';
    for (var ri=0; ri<7; ri++) {
      svgH += '.r'+ri+'{animation:rungFade 1.2s ease-in-out '+((ri*0.17).toFixed(2))+'s infinite}';
    }
    svgH += '</style>';
    // Strand A (left)
    svgH += '<g class="dna-sa" style="transform-origin:30px 40px">';
    svgH += '<path d="M14,4 C8,14 8,26 14,36 C20,46 20,58 14,68 C20,76 30,78 30,78" stroke="#8CB86E" stroke-width="1.8" fill="none" stroke-linecap="round" opacity="0.85"/>';
    svgH += '</g>';
    // Strand B (right)
    svgH += '<g class="dna-sb" style="transform-origin:30px 40px">';
    svgH += '<path d="M46,4 C52,14 52,26 46,36 C40,46 40,58 46,68 C40,76 30,78 30,78" stroke="#D4B455" stroke-width="1.8" fill="none" stroke-linecap="round" opacity="0.85"/>';
    svgH += '</g>';
    // Rungs
    var rungYs = [8,20,32,44,52,60,68];
    for (var ri=0; ri<7; ri++) {
      var ry = rungYs[ri];
      svgH += '<line x1="16" y1="'+ry+'" x2="44" y2="'+ry+'" stroke="rgba(140,184,110,0.4)" stroke-width="1" class="r'+ri+'"/>';
    }
    svgH += '</svg>';
    el.innerHTML = svgH +
      '<div class="dna-label">SPLICING DNA</div>' +
      '<div class="dna-sublabel">Combining genetic sequences…</div>';
    document.body.appendChild(el);
  }

  function showDNASplice(durationMs, callback) {
    _buildDNASpliceOverlay();
    var ov = document.getElementById('dna-splice-overlay');
    ov.classList.add('active');
    setTimeout(function() {
      ov.classList.remove('active');
      if (callback) callback();
    }, durationMs);
  }
