  function loadAchievements(){
    try{ return JSON.parse(localStorage.getItem(ACH_KEY)||'{}'); }catch(e){ return {}; }
  }
  function saveAchievements(a){ try{localStorage.setItem(ACH_KEY,JSON.stringify(a));}catch(e){} }

  function checkAchievements(){
    var unlocked = loadAchievements();
    var gh = loadGreenhouse();
    var records;
    try{ records = JSON.parse(localStorage.getItem('sws_streak')||'{}'); }catch(e){ records = {}; }
    var ledger = getHashLedger ? getHashLedger() : { spent: 0 };
    var compostLog;
    try{ compostLog = JSON.parse(localStorage.getItem('sws_compost_log')||'[]'); }catch(e){ compostLog = []; }
    var newlyUnlocked = [];
    ACHIEVEMENTS.forEach(function(ach){
      if (unlocked[ach.id]) return;
      var passed = false;
      try { passed = ach.check(gh, records, ledger, compostLog); } catch(e){}
      if (passed){
        unlocked[ach.id] = { unlockedAt: new Date().toISOString() };
        newlyUnlocked.push(ach);
      }
    });
    if (newlyUnlocked.length > 0){
      saveAchievements(unlocked);
      newlyUnlocked.forEach(function(ach){
        // Grant +25 Sunbeams via the proper earnHashes path
        if (typeof earnHashes === 'function') earnHashes(25);
        _showAchToast(ach);
        if (window.LW_Log) window.LW_Log.write('achievement_unlock', {
          id: ach.id, name: ach.name, icon: ach.icon, reward: 25
        });
        if(typeof gtag!=='undefined') gtag('event','achievement_unlock',{id:ach.id});
      });
      updateDashboard();
    }
    renderAchievements();
  }

  function _showAchToast(ach){
    var t = document.createElement('div');
    t.className = 'ach-toast';
    t.textContent = ach.icon + '  ' + ach.name + '  +25 ⚡';
    document.body.appendChild(t);
    setTimeout(function(){ t.remove(); }, 3200);
  }

  function renderAchievements(){
    var grid = document.getElementById('ach-grid');
    if (!grid) return;
    var unlocked = loadAchievements();
    grid.innerHTML = ACHIEVEMENTS.map(function(ach){
      var cls = unlocked[ach.id] ? 'ach-card unlocked' : 'ach-card';
      return '<div class="'+cls+'">' +
        '<div class="ach-icon">'+ach.icon+'</div>' +
        '<div><div class="ach-name">'+ach.name+'</div>' +
        '<div class="ach-desc">'+ach.desc+'</div>' +
        '<div class="ach-reward">'+( unlocked[ach.id] ? '✓ +25 ⚡ Claimed' : '+25 ⚡ on unlock' )+'</div></div>' +
        '</div>';
    }).join('');
  }
  // ═══ BINDER / PUBLIC GALLERY ═══
  window.renderBinder = function() {
    var container = document.getElementById('binder-grid-container');
    if (!container) return;
    var gh = loadGreenhouse().slice();
    if (gh.length === 0) {
      container.innerHTML = '<div class="binder-empty">No Plants yet.<br>Complete a game to mint your first.</div>';
      return;
    }
    var sel = document.getElementById('binder-sort-sel');
    var sort = sel ? sel.value : 'newest';
    if (sort === 'rarest') {
      gh.sort(function(a,b){ return ((b.rare?2:0)+(b.isCross?1:0)) - ((a.rare?2:0)+(a.isCross?1:0)); });
    } else if (sort === 'az') {
      gh.sort(function(a,b){ return getPlantName(a.hash).localeCompare(getPlantName(b.hash)); });
    } else {
      gh.reverse(); // newest first
    }
    // Phase 30: capture sorted array at render time for context-aware carousel
    var _binderArr = gh.slice(0); // snapshot of sorted array

    var html = '<div class="binder-grid">';
    gh.forEach(function(plant, i){
      var name = getPlantName(plant.hash);
      var haiku = getHaiku(plant.hash);
      var cls = 'binder-card' + (plant.rare?' rare':'') + (plant.isCross?' cross':'');
      var svgHtml = generatePlantSVG(plant.hash, 80);
      if (plant.mutated) svgHtml = svgHtml.replace('<svg ','<svg style="filter:drop-shadow(0 0 5px rgba(200,168,75,0.5));" ');
      // Binder cards open carousel with the SORTED binder array, not raw gh
      // Serialise the sorted array snapshot index (i) — not gh real index
      html += '<div class="'+cls+'" onclick="openCarousel(_lastBinderArr,' + i + ',\'binder\')">' +
        svgHtml +
        '<div class="binder-name">'+name+'</div>' +
        '<div class="binder-haiku">'+haiku.line1+'<br>'+haiku.line2+'</div>' +
        (function(){try{var _t=hashToTraits(plant.hash);var _sea=window.getSeasonInfo?window.getSeasonInfo(_t,plant):null;var _ea=window.computeEA?window.computeEA(_t,0,plant):0;var _tg=getTerraGrade(_t);return'<div style="display:flex;justify-content:center;gap:6px;margin:3px 0;font-size:0.35rem;"><span>'+(_sea?_sea.emblem:'')+'</span><span style="color:'+_tg.color+';opacity:0.7;">EA '+_ea+'</span></div>';}catch(e){return'';}})() +
        renderDNALedger(plant) +
        renderSubstrateBadge(plant) +
        '</div>';
    });
    // Phase 30: expose sorted snapshot globally so binder onclick can reference it
    window._lastBinderArr = _binderArr;

    html += '</div>';
    container.innerHTML = html;
  };
