  // ── badge state helpers ──────────────────────────────────────────────
  function _setBadgeVerified(name) {
    var badge = document.getElementById('sws-auth-badge');
    var label = document.getElementById('sws-badge-label');
    if (badge) {
      badge.className = 'verified';
      // onclick switches to mini-menu toggle when verified
      badge.onclick = function() { swsToggleMiniMenu(); };
    }
    if (label) {
      var display = name.length > 12 ? name.slice(0,12) + '…' : name;
      label.textContent = '⬡ DNA_SYNC: ' + display;
    }
  }

